const lanec_suite *lanec_find_suite(const char *name)
{
    unsigned i;
    for (i = 0; i < sizeof suites / sizeof suites[0]; ++i)
        if (!strcmp(suites[i]->name, name)) return suites[i];
    return 0;
}
